// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        amount = 10;
        vm.assume(address(this).balance >= amount);
        uint256 prePot;
        try c.pot() returns (uint256 __r) { prePot = __r; } catch { return; }
        uint preBankBal = c.bank().balance;
        try c.play{value: amount}() {} catch { return; }
        uint256 postPot;
        try c.pot() returns (uint256 __r) { postPot = __r; } catch { return; }
        uint postBankBal = c.bank().balance;
        bool bankReceivedFee = (postBankBal == preBankBal + 1);
        assertTrue(bankReceivedFee || postPot == prePot + amount || (postPot == 0 && prePot == 0));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
